"use strict";(self.webpackChunkizakharau_blog_docusaurus=self.webpackChunkizakharau_blog_docusaurus||[]).push([[1278],{4601:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>c,frontMatter:()=>i,metadata:()=>o,toc:()=>h});var o=n(8273),a=n(4848),r=n(8453);const i={date:new Date("2024-09-10T06:00:00.000Z"),description:"Onboarding is a crucial process when you are diving into a new product as a product manager. But if you take another product in the same organization that might sound not so challenging in comparison. But let's not underestimate that. I am experiencing a similar case, so I have something to reflect on. Follow me.",slug:"pm-onboarding-horizontal",tags:["Product Management","Product Strategy"],title:"PM Onboarding - Same Organization, New Area"},s="PM Onboarding - Same Organization, New Area",l={authorsImageUrls:[]},h=[{value:"Organizational knowledge - Headstart",id:"organizational-knowledge---headstart",level:2},{value:"Product knowledge - Free from bias and conflict of interest",id:"product-knowledge---free-from-bias-and-conflict-of-interest",level:2},{value:"Market knowledge - Don&#39;t pretend to know something",id:"market-knowledge---dont-pretend-to-know-something",level:2},{value:"Summary",id:"summary",level:2}];function d(e){const t={a:"a",em:"em",h2:"h2",img:"img",li:"li",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"cover",src:n(5799).A+"",width:"1024",height:"1024"})}),"\n",(0,a.jsx)(t.p,{children:'Onboarding is a crucial process of incorporating a new person into a team, product, or domain (for simplicity, let\'s generalize all that as "area"). The purpose is to align or increase performance as soon as possible after the unavoidable drop due to a structure change. If approached wrongly, it may cause substantial trouble, especially when you dive into a new area as a product manager (PM).'}),"\n",(0,a.jsx)(t.p,{children:'Whether it is a new or same organization, new role, or new area - the approach to onboarding will vary. Here, we talk about horizontal growth within an organization, keeping your role but acquiring a new "area" (for simplicity, let\'s use this term to generalize one or several products, teams, lines of business, etc). That is the situation I am currently in, so I have something to reflect on. Also, most onboarding guides focus on vertical growth with a new role in another business. So, it is a good topic to uncover.'}),"\n",(0,a.jsxs)(t.p,{children:['I follow the patterns of 3 key knowledge types in product management suggested in the "Building Products for Enterprise" book (I wrote about it ',(0,a.jsx)(t.a,{href:"https://ilyazakharau.com/reading-product-management-in-enterprise/",children:"here"}),"): organizational, product, and market knowledge. So, let's construct the onboarding strategy for each."]}),"\n",(0,a.jsx)(t.h2,{id:"organizational-knowledge---headstart",children:"Organizational knowledge - Headstart"}),"\n",(0,a.jsx)(t.p,{children:"When you start in another company, you must catch up quickly and demonstrate your best. When you move within the enterprise, you have a significant advantage."}),"\n",(0,a.jsx)(t.p,{children:"You know some people. Some people know you. Some people trust your expertise. You still need to prove that you can work in the new area. But your legacy will serve you, depending on your past success and prominence."}),"\n",(0,a.jsx)(t.p,{children:"You know and follow the established processes. You don't need to read boring brochures or watch uninspiring lectures."}),"\n",(0,a.jsx)(t.p,{children:"If you have worked there for some time, you understand the power dynamics. You also know your stakeholders and how to deal with them."}),"\n",(0,a.jsx)(t.p,{children:"Now, in the new area, you have new stakeholders. You need to build a bridge between you. They likely don't consider your successful legacy from the start. So please don't be arrogant."}),"\n",(0,a.jsx)(t.p,{children:"The team you joined (they are stakeholders, too) might have existed for a long time. The PM change is as stressful for them as any other change. You must be very cautious in presenting yourself and with your first actions."}),"\n",(0,a.jsxs)(t.p,{children:["As a product manager, you have your tools and ways of doing things. First, quoting Matt LeMay's book (",(0,a.jsx)(t.a,{href:"https://ilyazakharau.com/product-management-in-practice/",children:"here"}),'), "Don\'t break the rules; change them." And change them with great patience by investing time in understanding how the team operates and why.']}),"\n",(0,a.jsx)(t.p,{children:"Another trick is that you might inherit current stakeholders from a previous area. Even though you are the same people with the same relationships, now they probably have a different perspective on you."}),"\n",(0,a.jsx)(t.p,{children:"Spend time identifying that perspective with the implied expectations. Then, keep revisiting and re-arranging your interactions: some may play a more prominent role and have a more significant influence, and some may be less relevant, but you still need to be in touch with them."}),"\n",(0,a.jsx)(t.h2,{id:"product-knowledge---free-from-bias-and-conflict-of-interest",children:"Product knowledge - Free from bias and conflict of interest"}),"\n",(0,a.jsx)(t.p,{children:"While working in an enterprise, there is a chance that you've already interacted with the area you are now in charge of. You might have biases towards that area depending on your experience of those interactions."}),"\n",(0,a.jsx)(t.p,{children:"You'd better not underestimate the complexity by expecting quickly rich success as soon as you arrive in shiny armor. If you do, lucky you - I want to learn that from you. For the rest, mere mortals, including me, reset your knowledge of the area and product and start from scratch, free from biases."}),"\n",(0,a.jsx)(t.p,{children:"You might also have been a stakeholder (or continue to be a stakeholder, as in my case) in that area before joining it as a PM, which can lead to a conflict of interest."}),"\n",(0,a.jsx)(t.p,{children:"You can prioritize your stakeholder interest or the interests of a stakeholder group you were part of. Of course, it is at the cost of the others. Even though that may lead to some short-term gains, it is damaging in the long term. And I am not mentioning spoiling relationships as a PM with your new stakeholders. Please avoid that by having a holistic view of such things."}),"\n",(0,a.jsx)(t.p,{children:"Beyond that, do the usual onboarding activities: learn a product by trying to use it (even though you may not be a target audience), read the documentation, ask questions to the team, talk to users, talk to experts, etc."}),"\n",(0,a.jsx)(t.h2,{id:"market-knowledge---dont-pretend-to-know-something",children:"Market knowledge - Don't pretend to know something"}),"\n",(0,a.jsx)(t.p,{children:"It's a similar situation here: having your previous experience, you might already know something about the new area's market. This is less likely if it is a new market and more likely if it is another line of business."}),"\n",(0,a.jsx)(t.p,{children:"The same advice applies here: don't be biased. The rules you know might not work here."}),"\n",(0,a.jsx)(t.p,{children:"For example, I move from API to UI platform as a new area. Even though they are both platforms for developers who build insurance products, they are different worlds. As different worlds, they speak different languages, have their own context and history, worship other things, and have different world views."}),"\n",(0,a.jsx)(t.p,{children:"My decade-old pet project experience as a Front-end developer does not give me any valuable knowledge, so I don't pretend I know something. I only admit there is a long way to go."}),"\n",(0,a.jsx)(t.p,{children:"Market knowledge takes the longest to acquire. You can't download all information about competitors, trends, and historical contexts and store it in your brain, so take your time."}),"\n",(0,a.jsx)(t.h2,{id:"summary",children:"Summary"}),"\n",(0,a.jsx)(t.p,{children:"Acquiring a new area as a product manager within your current organization gives you an evident advantage over a new hire. However, you'd better use it wisely:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Leverage your existing knowledge of an organization."}),"\n",(0,a.jsx)(t.li,{children:"Embrace new stakeholders and revisit your relationships with current ones."}),"\n",(0,a.jsx)(t.li,{children:"Don't be arrogant with the team; don't break things."}),"\n",(0,a.jsx)(t.li,{children:"Avoid conflict of interest."}),"\n",(0,a.jsx)(t.li,{children:"Learn how to use your new product and how others use it."}),"\n",(0,a.jsx)(t.li,{children:"Don't pretend you know something."}),"\n",(0,a.jsx)(t.li,{children:"Invest in market research."}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.em,{children:"Take care"}),","]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"Ilya"})})]})}function c(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},5799:(e,t,n)=>{n.d(t,{A:()=>o});const o=n.p+"assets/images/pm_onboarding-fa028b9d19f83592ce34236265f9a5be.jpg"},8273:e=>{e.exports=JSON.parse('{"permalink":"/blog/pm-onboarding-horizontal","source":"@site/blog/2024/pm-onboarding-horizontal.md","title":"PM Onboarding - Same Organization, New Area","description":"Onboarding is a crucial process when you are diving into a new product as a product manager. But if you take another product in the same organization that might sound not so challenging in comparison. But let\'s not underestimate that. I am experiencing a similar case, so I have something to reflect on. Follow me.","date":"2024-09-10T06:00:00.000Z","tags":[{"inline":true,"label":"Product Management","permalink":"/blog/tags/product-management"},{"inline":true,"label":"Product Strategy","permalink":"/blog/tags/product-strategy"}],"readingTime":5.07,"hasTruncateMarker":true,"authors":[],"frontMatter":{"date":"2024-09-10T06:00:00.000Z","description":"Onboarding is a crucial process when you are diving into a new product as a product manager. But if you take another product in the same organization that might sound not so challenging in comparison. But let\'s not underestimate that. I am experiencing a similar case, so I have something to reflect on. Follow me.","slug":"pm-onboarding-horizontal","tags":["Product Management","Product Strategy"],"title":"PM Onboarding - Same Organization, New Area"},"unlisted":false,"prevItem":{"title":"BArszawa Blog #6 (September\'24)","permalink":"/blog/barszawa-blog-edition-06-2024"},"nextItem":{"title":"TRANSFORMED - Some Thoughts After Reading","permalink":"/blog/transformed-book"}}')},8453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>s});var o=n(6540);const a={},r=o.createContext(a);function i(e){const t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);